    inventory_items = inventory_data
else:
    inventory_items = inventory_data.get(
        "items",
        inventory_data.get("inventory", inventory_data.get("data", [])),
    )

insufficient_items = [
    item for item in inventory_items
    if isinstance(item, dict) and item.get("quantity", 0) <= item.get("predictedQuantity", 0)
]

