    order_response = requests.post(
        f"{BASE_URL}/orders",
        json={
            "items": [
                {
                    "itemId": item.get("itemId", item.get("id")),
                    "quantity": max(
                        0,
                        item.get("predictedQuantity", 0) - item.get("quantity", 0),
                    ),
                }
                for item in insufficient_items
