import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

def get(path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    return response.json()

def post(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload)
    response.raise_for_status()
    return response.json() if response.content else None

def put(path, payload):
    response = session.put(f"{BASE_URL}{path}", json=payload)
    response.raise_for_status()
    return response.json() if response.content else None

alerts = get("/alerts")
patients = get("/patients")
patients_by_id = {
    str(patient.get("id", patient.get("patient_id"))): patient
    for patient in patients
    if patient.get("id", patient.get("patient_id")) is not None
}

results = []

for alert in alerts:
    patient_id = alert.get("patient_id")
    if patient_id is None:
        continue

    patient_id = str(patient_id)
    patient = patients_by_id.get(patient_id)
    if patient is None:
        patient = get(f"/patients/{patient_id}")

    policy_id = alert.get("policy_id") or patient.get("policy_id")
    policy_validation = None
    if policy_id:
        policy_validation = post(
            "/policies/validate",
            {
                "policy_id": policy_id,
                "patient_id": patient_id,
                "service": alert.get("service"),
            },
        )

    readings = get(f"/readings/{patient_id}")
    records = get(f"/patients/{patient_id}/records")
    medical_history = get(f"/patients/{patient_id}/history")

    findings = {
        "alert": alert,
        "policy_validation": policy_validation,
        "readings": readings,
        "records": records,
        "medical_history": medical_history,
    }

    post(
        f"/records/{patient_id}",
        {
            "type": "significant_findings",
            "date": alert.get("created_at"),
            "findings": findings,
        },
    )

    claim_id = alert.get("claim_id")
    if claim_id:
        put(
            f"/claims/{claim_id}",
            {
                "patient_id": patient_id,
                "significant_findings": findings,
            },
        )

    results.append(
        {
            "patient_id": patient_id,
            "findings": findings,
            "alert": alert,
        }
    )

compliance_status = get("/compliance/status")

print(
    {
        "processed_patients": results,
        "compliance_status": compliance_status,
        "alert_dismissal": "No alert dismissal endpoint is documented.",
    }
)

